package com.zhou.craft.controller;
import com.zhou.craft.dto.ProgressForm;import com.zhou.craft.model.CraftOrder;import com.zhou.craft.repo.*;import com.zhou.craft.security.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/orders")public class OrderController{
private final CraftOrderRepository orders;private final CustomRequestRepository requests;private final QuoteRepository quotes;private final OrderAccessService access;
public OrderController(CraftOrderRepository o,CustomRequestRepository r,QuoteRepository q,OrderAccessService a){orders=o;requests=r;quotes=q;access=a;}
@GetMapping public List<CraftOrder> list(){var p=AuthContext.require();if("USER".equals(p.role()))return orders.findByCustomerIdOrderByCreatedAtDesc(p.id());if("CREATOR".equals(p.role()))return orders.findByCreatorIdOrderByCreatedAtDesc(p.id());return orders.findAllByOrderByCreatedAtDesc();}
@PostMapping("/from-quote/{quoteId}")public CraftOrder create(@PathVariable Long quoteId){var p=access.requireRole("USER");var q=quotes.findById(quoteId).orElseThrow();var r=requests.findById(q.getRequestId()).orElseThrow();if(!p.id().equals(r.getUserId()))throw new IllegalStateException("不能使用其他用户需求生成订单");r.setStatus("已转订单");requests.save(r);return orders.save(new CraftOrder(r.getId(),q.getId(),p.id(),q.getCreatorId(),r.getTitle(),p.displayName(),q.getCreatorName(),q.getPrice(),q.getLeadDays()));}
@PutMapping("/{id}/progress")public CraftOrder progress(@PathVariable Long id,@RequestBody ProgressForm f){var o=orders.findById(id).orElseThrow();access.requireCreator(o);o.updateProgress(f.progress(),f.text());return orders.save(o);}
@PutMapping("/{id}/complete")public CraftOrder complete(@PathVariable Long id){var o=orders.findById(id).orElseThrow();access.requireCustomer(o);o.complete();return orders.save(o);}
@PostMapping("/{id}/cancel-request")public CraftOrder cancel(@PathVariable Long id){var o=orders.findById(id).orElseThrow();access.requireCustomer(o);o.requestCancel();return orders.save(o);}
}